  FT["PH-H8079"] = {"id":"PH-H8079","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2009/ra_9620_2009.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Victorias市","en":"An Act Converting the Negros Occidental Science High School in the City of Victorias, Province of Negros Occidental into a National Science High School to Be Known as Negros Occidental National Science High School and Appropriating Funds Therefor","orig":"An Act Converting the Negros Occidental Science High School in the City of Victorias, Province of Negros Occidental into a National Science High School to Be Known as Negros Occidental National Science High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 9620","issuingBody":"Congress of the Philippines","promulgatedDate":"2009-05-13","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2009/ra_9620_2009.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8079-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Conversion into a National Science High School. - The Negros Occidental Science High School in the City of Victorias, Province of Negros Occidental is hereby converted into a national science high school to be known as Negros Occidental National Science High School."}},{"id":"PH-H8079-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. - All personnel, assets, liabilities and records of the Negros Occidental Science High School are hereby transferred to and absorbed by the Negros Occidental National Science High School."}},{"id":"PH-H8079-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. - The Secretary of Education shall immediately include in the Department’s program the operationalization of the Negros Occidental National Science High School, the initial funding of which shall be charged against the current year’s appropriations of the Negros Occidental Science High School. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8079-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. - The Secretary of Education shall issue such rules and regulations as may he necessary to carry out the purpose of this Act."}},{"id":"PH-H8079-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p115"};
