  FT["PH-H8087"] = {"id":"PH-H8087","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2009/ra_9628_2009.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Pilar市","en":"An Act Converting the Pilar Productivity Development High School in the Municipality of Pilar, Province of Sorsogon into a National High School to Be Known as Pilar National Comprehensive High School and Appropriating Funds Therefor.","orig":"An Act Converting the Pilar Productivity Development High School in the Municipality of Pilar, Province of Sorsogon into a National High School to Be Known as Pilar National Comprehensive High School and Appropriating Funds Therefor."},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 9628","issuingBody":"Congress of the Philippines","promulgatedDate":"2009-05-13","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2009/ra_9628_2009.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8087-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Conversion into a National High School. - The Pilar Productivity Development High School in the Municipality of Pilar, Province of Sorsogon is hereby converted into a national high school to be known as Pilar National Comprehensive High School."}},{"id":"PH-H8087-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. - All personnel, assets, liabilities and records of the Pilar Productivity Development High School are hereby transferred to and absorbed by the Pilar NationaI Comprehensive High School."}},{"id":"PH-H8087-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. – The Secretary of Education shall immediately include in the Department’s program the operationalization of the Pilar National Comprehensive High School, the initial funding of which shall be charged against the current year’s appropriations of the Pilar Productivity Development High School. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8087-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. - The Secretary of Education shall issue rules and regulations that may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8087-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p115"};
