  FT["PH-H8116"] = {"id":"PH-H8116","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2009/ra_9658_2009.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Lian市","en":"An Act Establishing a National High School in Barangay Malaruhatan, Municipality of Lian, Province of Batangas to Be Known as Lian National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Malaruhatan, Municipality of Lian, Province of Batangas to Be Known as Lian National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 9658","issuingBody":"Congress of the Philippines","promulgatedDate":"2009-07-17","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2009/ra_9658_2009.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8116-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Establishment of a National High School. - There is hereby established, under the supervision of the Department of Education, a national high school in Barangay Malaruhatan, Municipality of Lian, Province of Batangas to be known as Lian National High School."}},{"id":"PH-H8116-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Appropriations. - The Secretary of Education shall immediately include in the Department's program the operationalization of Lian National High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8116-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Implementation. - The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8116-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p115"};
  FT["PH-H8117"] = {"id":"PH-H8117","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2009/ra_9659_2009.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Separating the Valenzuela National High School - Punturin Annex in Barangay Punturin, City of Valenzuela, Metro Manila from the Valenzuela National High School, Converting it into an Independent National High School to Be Known as Vicente P. Trinidad National High School and Appropriating Funds Therefor","orig":"An Act Separating the Valenzuela National High School - Punturin Annex in Barangay Punturin, City of Valenzuela, Metro Manila from the Valenzuela National High School, Converting it into an Independent National High School to Be Known as Vicente P. Trinidad National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 9659","issuingBody":"Congress of the Philippines","promulgatedDate":"2009-07-17","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2009/ra_9659_2009.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8117-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Separation and Conversion into a National High School. - The Valenzuela National High School - Punturin Annex in Barangay Punturin, City of Valenzuela, Metro Manila is hereby separated from the Valenzuela National High School and converted into an independent national high school to be known as Vicente P. Trinidad National High School."}},{"id":"PH-H8117-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. - All personnel, assets, liabilities and records of the Valenzuela National High School - Punturin Annex are hereby transferred to and absorbed by the Vicente P. Trinidad National High School."}},{"id":"PH-H8117-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. - The Secretary of Education shall immediately include in the Department’s program the operationalization of the Vicente P. Trinidad National High School, the initial funding of which shall be charged against the current year’s appropriations of the Valenzuela National High School - Punturin Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8117-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. - The Secretary of Education shall issue rules and regulations that may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8117-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (16) days after its publication in the Official Gazette."}}],"pack":"ph-p115"};
  FT["PH-H8118"] = {"id":"PH-H8118","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2009/ra_9660_2009.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Separating the Valenzuela National High School - Bignay Annex in Barangay Bignay, City of Valenzuela from the Valenzuela National High School, Converting it into an Independent National High School to Be Known as Bignay National High School and Appropriating Funds Therefor","orig":"An Act Separating the Valenzuela National High School - Bignay Annex in Barangay Bignay, City of Valenzuela from the Valenzuela National High School, Converting it into an Independent National High School to Be Known as Bignay National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 9660","issuingBody":"Congress of the Philippines","promulgatedDate":"2009-07-17","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2009/ra_9660_2009.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8118-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Separation and Conversion into a National High School. - The Valenzuela National High School - Bignay Annex in Barangay Bignay, City of Valenzuela is hereby separated from the Valenzuela National High School and converted into an independent national high school to be known as Bignay National High School."}},{"id":"PH-H8118-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. - All personnel, assets, liabilities and records of the Valenzuela National High School - Bignay Annex are hereby transferred to and absorbed by the Bignay National High School."}},{"id":"PH-H8118-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. - The Secretary of Education shall immediately include in the Department's program the operationalization of the Bignay National High School, the initial funding of which shall be charged against the current year's appropriations of the Valenzuela National High School - Bignay Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8118-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. - The Secretary of Education shall issue rules and regulations that may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8118-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication the Official Gazette."}}],"pack":"ph-p115"};
